<script setup lang="ts">
import {defineAsyncComponent,ref,onMounted,onBeforeUnmount} from 'vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import UiButton from '@/components/ui/UiButton.vue'
import {useSyncStore} from './store'
import {errorText} from '@/features/models/api'
import {getSyncConfig,saveSyncEndpoint,testSyncCandidate} from './api'
const ImportedConnections=defineAsyncComponent(()=>import('./ImportedConnections.vue'));const importedOpen=ref(false)
const emit=defineEmits<{close:[]}>();const sync=useSyncStore();const busy=ref(false),testing=ref(false),message=ref(''),error=ref('')
const value=ref({baseUrl:'',remotePath:'',username:'',password:'',conflictPolicy:'ask' as const})
const loading=ref(true),ready=ref(false)
async function load(){loading.value=true;error.value='';try{sync.config=await getSyncConfig();const e=sync.config.endpoint;if(e)value.value={baseUrl:e.url,remotePath:e.remotePath,username:e.username,password:'',conflictPolicy:'ask'};ready.value=true}catch{error.value='无法读取已保存连接；请重新读取后再保存。';ready.value=false}finally{loading.value=false}}
onMounted(load)
onBeforeUnmount(()=>{value.value.password=''})
function valid(){if(!value.value.baseUrl.startsWith('https://')){error.value='请填写 HTTPS 服务地址。';return false}if(!value.value.remotePath.trim()||!value.value.username.trim()){error.value='请填写独立目录和用户名。';return false}if(!value.value.password&&(!sync.config?.endpoint||sync.config.endpoint.url.replace(/\/$/,'')!==value.value.baseUrl.replace(/\/$/,'')||sync.config.endpoint.username!==value.value.username)){error.value='新连接或更换服务地址、用户名后，请填写连接密码。';return false}return true}
async function test(){if(busy.value||testing.value||!ready.value||!valid())return;testing.value=true;message.value='';error.value='';try{const result=await testSyncCandidate({...value.value});if(result.operationState==='succeeded')message.value=result.message;else error.value=result.message}catch(e){error.value=errorText(e)}finally{testing.value=false}}
async function save(){if(busy.value||testing.value||!ready.value||!valid())return;busy.value=true;error.value='';try{sync.config=await saveSyncEndpoint(value.value);emit('close')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script>
<template><UiDialog hide-close :open="true" title="WebDAV 连接" :busy="busy||testing" panel-class="sync-connection-dialog" @close="emit('close')"><div class="sx-connection-fields"><label><span>服务地址</span><input :disabled="busy||testing||loading" v-model="value.baseUrl" class="input" autocapitalize="off" autocorrect="off" spellcheck="false" /></label><label><span>独立配置同步目录</span><input :disabled="busy||testing||loading" v-model="value.remotePath" class="input" autocapitalize="off" autocorrect="off" spellcheck="false" /></label><div class="sx-grid"><label><span>用户名</span><input :disabled="busy||testing||loading" v-model="value.username" class="input" autocapitalize="off" autocorrect="off" spellcheck="false" /></label><label><span>连接密码</span><input :disabled="busy||testing||loading" v-model="value.password" type="password" class="input" autocomplete="new-password" :placeholder="sync.config?.endpoint?'本机已保存 · 留空保留':'填写连接密码'" /></label></div><div><UiButton :loading="testing" :disabled="busy||testing||!ready" @click="test">测试连接</UiButton></div><UiButton v-if="!ready&&!loading" :disabled="busy||testing" @click="load">重新读取</UiButton><p v-if="message" class="model-muted" role="status">{{ message }}</p><p v-if="error" class="model-error" role="alert">{{ error }}</p><details class="sx-imported-connections" @toggle="importedOpen=($event.target as HTMLDetailsElement).open"><summary>导入的连接</summary><ImportedConnections v-if="importedOpen" @activated="load" /></details></div><template #actions><UiButton :disabled="busy||testing" @click="emit('close')">取消</UiButton><UiButton variant="primary" :loading="busy" :disabled="busy||testing||!ready" @click="save">保存连接</UiButton></template></UiDialog></template>
<style scoped>:global(.sync-connection-dialog.ui-dialog){width:min(720px,calc(86vw / var(--ui-zoom)));max-height:calc(78vh / var(--ui-zoom))}.sx-connection-fields,.sx-connection-fields label{display:grid;gap:8px}.sx-connection-fields{gap:16px}.sx-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.model-error{color:var(--red)}@media(max-width:600px){.sx-grid{grid-template-columns:1fr}}</style>
